import { useEffect, useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { callOperation, streamQuery, type Contract } from './generated-client';
import { queryClient, useQueryIdentity } from './query-cache';
import { RequestError, session } from './transport';
import { parseExactJSON, stringifyExactJSON } from './precision';
import { applyWindowEvent, snapshotWindow, type QueryKind, type WindowState } from './query-window';
import type { DataResult, Entity, Json } from './types';

export async function queryPage(kind: QueryKind, body: Contract<'QueryRequest'>, signal?: AbortSignal) {
  return callOperation('post_queries_kind', { parameters: { path: { kind } }, body }, { signal, exact: true });
}
export function useWindowQuery(kind: QueryKind | null, scope: Contract<'QueryRequest'>, refreshMS = 0) {
  const identity = useQueryIdentity();
  const scopeKey = stringifyExactJSON(scope);
  const queryKey = ['window', identity.key, kind, scopeKey];
  const [streamError, setStreamError] = useState('');
  const [streamStatus, setStreamStatus] = useState('查询');
  const result = useQuery({ queryKey, enabled: identity.enabled && !!kind, queryFn: async ({ signal }) => snapshotWindow(await queryPage(kind!, parseExactJSON(scopeKey) as Contract<'QueryRequest'>, signal)), refetchInterval: refreshMS > 0 ? refreshMS : false, refetchOnWindowFocus: refreshMS !== -1 });
  useEffect(() => {
    setStreamError('');
    if (!identity.enabled || !kind || refreshMS !== -1 || scope.page_token) { setStreamStatus('查询'); return; }
    const controller = new AbortController(); let timer: number | undefined;
    const connect = async () => {
      const previous = queryClient.getQueryData<WindowState>(queryKey);
      setStreamStatus(previous?.cursor ? '恢复订阅' : '建立订阅');
      try {
        const body = await streamQuery(kind, parseExactJSON(scopeKey) as Contract<'QueryRequest'>, previous?.cursor ?? '', controller.signal);
        const reader = body.getReader(); const decoder = new TextDecoder(); let pending = '';
        for (;;) {
          const chunk = await reader.read(); if (chunk.done) break;
          pending += decoder.decode(chunk.value, { stream: true }).replace(/\r\n/g, '\n');
          let end: number;
          while ((end = pending.indexOf('\n\n')) >= 0) {
            const block = pending.slice(0, end); pending = pending.slice(end + 2);
            const lines = block.split('\n');
            const text = lines.filter(line => line.startsWith('data:')).map(line => line.slice(5).trimStart()).join('\n');
            if (!text) { setStreamStatus('订阅已连接'); continue; }
            const event = parseExactJSON(text) as Contract<'QueryEvent'>;
            const eventID = lines.find(line => line.startsWith('id:'))?.slice(3).trim() ?? '';
            if (event.type === 'reset') {
              if (event.clear) { void queryClient.cancelQueries(); queryClient.clear(); }
              if (/(authorization|session|authentication)/.test(event.reason ?? '')) window.dispatchEvent(new Event('sf-authz-changed'));
              else await result.refetch();
              setStreamError('订阅重新取得快照：' + (event.reason ?? '查询状态变化'));
              await reader.cancel();
              if (event.retryable === false) return;
              break;
            }
            if (!controller.signal.aborted) queryClient.setQueryData<WindowState>(queryKey, old => {
              if (event.type === 'snapshot' && event.page) return snapshotWindow(event.page, eventID || event.cursor);
              return old ? applyWindowEvent(old, event, eventID) : old;
            });
            setStreamStatus('订阅已连接'); setStreamError('');
          }
        }
      } catch (error) {
        if (!controller.signal.aborted) {
          if (error instanceof RequestError && error.status === 401) window.dispatchEvent(new Event('sf-auth-expired'));
          else if (error instanceof RequestError && error.status === 403) window.dispatchEvent(new Event('sf-authz-changed'));
          setStreamError(error instanceof Error ? error.message : String(error));
        }
      }
      if (!controller.signal.aborted) { setStreamStatus('等待恢复'); timer = window.setTimeout(() => void connect(), 1000); }
    };
    void connect();
    return () => { controller.abort(); if (timer) clearTimeout(timer); };
  }, [identity.key, identity.enabled, kind, scopeKey, refreshMS]);
  const reload = async () => { setStreamError(''); return result.refetch(); };
  return { data: identity.enabled ? result.data?.page : undefined, cursor: result.data?.cursor ?? '', error: result.error instanceof Error ? result.error.message : streamError, loading: result.isFetching, updatedAt: result.dataUpdatedAt, reload, streamStatus };
}
export async function queryAllPages(kind: QueryKind, scope: Contract<'QueryRequest'>, signal?: AbortSignal) {
  const items: Contract<'QueryRow'>[] = []; let pageToken: string | undefined;
  for (;;) {
    const page = await queryPage(kind, { ...scope, page_token: pageToken }, signal); items.push(...page.items ?? []);
    if (!page.has_more || !page.next_page_token) return { ...page, items };
    pageToken = page.next_page_token;
  }
}
export function queryData(page?: Contract<'QueryPage'>): DataResult | null {
  if (!page) return null;
  return { points: (page.items ?? []).map(row => row.data) as DataResult['points'], quality: (page.metadata?.quality ?? {good:0,bad:0,uncertain:0,excluded:0,missing:null,completeness:'unknown'}) as DataResult['quality'], sources: (page.metadata?.sources ?? []) as DataResult['sources'], revisions: (page.metadata?.revisions ?? []) as DataResult['revisions'], gaps: page.metadata?.gaps as DataResult['gaps'], data_version: 0, truncated: !!page.has_more };
}
export function legacyScope(path: string | null): { kind: QueryKind | null; scope: Contract<'QueryRequest'> } {
  const [pathname, search] = (path ?? '').split('?'); const params = new URLSearchParams(search);
  if (pathname === '/entities' || pathname === '/alarms' || pathname === '/executions') return { kind: pathname.slice(1) as QueryKind, scope: { limit: 500 } };
  if (pathname !== '/data') return { kind: null, scope: {} };
  return { kind: 'trend', scope: { resource_ids: params.get('device_ids')?.split(',') ?? [], keys: params.get('keys')?.split(',') ?? [], from_ms: Number(params.get('from_ms')) || Date.now() - (Number(params.get('window_ms')) || 3600000), to_ms: Number(params.get('to_ms')) || Date.now() + 30000, resolution: params.get('resolution') || 'raw', limit: Math.min(Number(params.get('limit')) || 100, 2000) } };
}

import type { Contract } from './generated-client';

export type QueryKind = 'entities' | 'alarms' | 'executions' | 'trend';
export type WindowState = { page: Contract<'QueryPage'>; cursor: string; revisions: Record<string, string> };
export const rowIdentity = (row: Pick<Contract<'QueryRow'>, 'kind' | 'id'>) => `${row.kind}:${row.id}`;
export function snapshotWindow(page: Contract<'QueryPage'>, cursor = page.snapshot_cursor ?? ''): WindowState {
  return { page, cursor, revisions: Object.fromEntries((page.items ?? []).map(row => [rowIdentity(row), row.revision ?? '0'])) };
}
export function applyWindowEvent(state: WindowState, event: Contract<'QueryEvent'>, eventID: string): WindowState {
  if (event.type === 'snapshot' && event.page) return snapshotWindow(event.page, eventID || event.cursor);
  if (event.type !== 'delta' && event.type !== 'checkpoint') return state;
  const revisions = { ...state.revisions };
  const rows = new Map((state.page.items ?? []).map(row => [rowIdentity(row), row]));
  for (const change of event.changes ?? []) {
    const id = rowIdentity(change);
    if (BigInt(change.revision ?? '0') < BigInt(revisions[id] ?? '0')) continue;
    revisions[id] = change.revision ?? '0';
    if (change.operation === 'remove') rows.delete(id);
    else if (change.item) rows.set(id, change.item);
  }
  const items = [...rows.values()].sort((a, b) => Number(b.sort_ms) - Number(a.sort_ms) || (String(a.id) < String(b.id) ? -1 : String(a.id) > String(b.id) ? 1 : 0));
  return { page: { ...state.page, items, metadata: event.metadata ?? state.page.metadata, has_more: event.has_more ?? state.page.has_more }, cursor: eventID || event.cursor || state.cursor, revisions };
}

import { createContext, useContext, useEffect, useState, type ReactNode } from 'react';
import { Alert, Button, Form, Input, Select, Space, Tabs, Tag } from 'antd';
import { json } from './api';
import type { Contract } from './generated-client';
import { parseExactJSON, stringifyExactJSON } from './precision';

export type FieldMetadata = Contract<'ParameterMetadata'> & { sensitive?: boolean };
export type Parameters = Record<string, unknown>;
const FieldValidity = createContext<(id:string,error:string)=>void>(()=>{});
export function MetadataValidationScope({children,onChange}:{children:ReactNode;onChange:(errors:string[])=>void}) {
  const [errors,setErrors] = useState<Record<string,string>>({}); const errorKey = JSON.stringify(errors);
  useEffect(()=>onChange(Object.values(errors).filter(Boolean)),[errorKey]);
  return <FieldValidity.Provider value={(id,error)=>setErrors(old=>old[id]===error?old:{...old,[id]:error})}>{children}</FieldValidity.Provider>;
}
export { parseField, metadataIssues } from './metadata-values';
import { parseField, metadataIssues } from './metadata-values';
export function MetadataFields({ fields, value, onChange, prefix = '' }: { fields: FieldMetadata[]; value: Parameters; onChange: (value: Parameters) => void; prefix?: string }) {
  const set = (key: string, item: unknown) => { const next = { ...value }; if (item === undefined) delete next[key]; else next[key] = item; onChange(next); };
  return <Form component={false} layout="vertical" className="metadata-fields">{fields.map(field => <MetadataField key={field.key} field={field} value={value[field.key ?? '']} onChange={item => set(field.key ?? '', item)} prefix={prefix} />)}</Form>;
}
function MetadataField({ field, value, onChange, prefix }: { field: FieldMetadata; value: unknown; onChange: (value: unknown) => void; prefix: string }) {
  const validity = useContext(FieldValidity);
  const display = (item: unknown) => item === undefined ? '' : field.type === 'string' ? String(item) : stringifyExactJSON(item);
  const [text, setText] = useState(() => display(value)); const [error, setError] = useState('');
  useEffect(() => { setText(display(value)); }, [value]);
  const label = `${prefix}${field.label || field.key}${field.unit ? '（' + field.unit + '）' : ''}`;
  const update = (text: string) => { setText(text); try { const item = parseField(field, text); onChange(item); setError(''); validity(prefix + field.key,''); } catch (error) { const message = error instanceof Error ? error.message : String(error); setError(message); validity(prefix + field.key,message); } };
  return <Form.Item label={label} required={field.required} help={error || field.description} validateStatus={error ? 'error' : undefined}>
    {field.enum?.length ? <Select aria-label={label} allowClear={!field.required} value={value === undefined ? undefined : String(value)} onChange={item => update(item ?? '')} options={field.enum.map(item => ({ value: item, label: item }))} />
      : field.type === 'boolean' ? <Select aria-label={label} allowClear value={value === undefined ? undefined : String(value)} onChange={item => update(item ?? '')} options={[{ value: 'true', label: '启用' }, { value: 'false', label: '停用' }]} />
      : field.type === 'json' ? <Input.TextArea aria-label={label} rows={3} value={text} onChange={event => update(event.target.value)} />
      : field.sensitive ? <Input.Password aria-label={label} value={text} onChange={event => update(event.target.value)} autoComplete="new-password" />
      : <Input aria-label={label} value={text} onChange={event => update(event.target.value)} inputMode={['integer', 'number'].includes(field.type ?? '') ? 'decimal' : 'text'} />}
    {(field.minimum !== undefined || field.maximum !== undefined) && <small className="muted">允许范围 {String(field.minimum ?? '不限')} 至 {String(field.maximum ?? '不限')}</small>}
  </Form.Item>;
}
export function NodeParameterForm({ metadata, parameters, onApply }: { metadata: Contract<'NodeMetadata'>; parameters: Parameters; onApply: (parameters: Parameters) => void }) {
  const [fieldErrors,setFieldErrors] = useState<string[]>([]); const [value, setValue] = useState(parameters); const [error, setError] = useState(''); const [rawError, setRawError] = useState(''); const [text, setText] = useState(json(parameters));
  useEffect(() => { setValue(parameters); setText(json(parameters)); setError(''); setRawError(''); }, [parameters]);
  const apply = () => { if (rawError || fieldErrors.length) {setError(rawError || fieldErrors.join('；'));return;} const issues = metadataIssues(metadata.parameters ?? [], value); if (issues.length) setError(issues.join('；')); else { setError(''); onApply(value); } };
  return <MetadataValidationScope onChange={setFieldErrors}><p>{metadata.description}</p><Space wrap>{(metadata.inputs ?? []).map(port => <Tag key={'in' + port.name}>输入 {port.name} / {port.type}</Tag>)}{(metadata.outputs ?? []).map(port => <Tag key={'out' + port.name}>输出 {port.name} / {port.type}</Tag>)}</Space><Tabs items={[{ key: 'fields', label: '基础参数', children: <MetadataFields fields={metadata.parameters ?? []} value={value} onChange={next => { setValue(next); setText(json(next)); setRawError(''); }} /> }, { key: 'extensions', label: '完整参数与扩展', children: <Input.TextArea aria-label="节点完整参数" rows={10} value={text} onChange={event => { setText(event.target.value); try { const next = parseExactJSON(event.target.value); if (!next || typeof next !== 'object' || Array.isArray(next)) throw new Error('参数需要 JSON 对象'); setValue(next as Parameters); setError(''); setRawError(''); } catch (error) { setRawError(String(error)); } }} /> }]} />{(error || rawError) && <Alert type="error" title="节点参数需要调整" description={rawError || error} />}<Button type="primary" disabled={!!fieldErrors.length || !!rawError} onClick={apply}>应用基础参数</Button></MetadataValidationScope>;
}
function getPath(value: Parameters, path: string): unknown { return path.split('.').reduce<unknown>((item, key) => item && typeof item === 'object' ? (item as Parameters)[key] : undefined, value); }
function setPath(value: Parameters, path: string, item: unknown): Parameters { const next = structuredClone(value); const keys = path.split('.'); let parent = next; keys.slice(0, -1).forEach(key => { if (!parent[key] || typeof parent[key] !== 'object') parent[key] = {}; parent = parent[key] as Parameters; }); parent[keys.at(-1)!] = item; return next; }
export function ProtocolParameterForm({ metadata, value, onChange }: { metadata: Contract<'ProtocolMetadata'>; value: Parameters; onChange: (value: Parameters) => void }) {
  return <Tabs className="protocol-tabs" items={(metadata.sections ?? []).map(section => {
    const path = section.path ?? ''; const item = getPath(value, path);
    const edit = (next: unknown) => onChange(setPath(value, path, next));
    if (section.repeated) { const items = Array.isArray(item) ? item as Parameters[] : []; return { key: path, label: path === 'datapoints' ? '数据点' : path, children: <>{items.map((point, index) => <div className="parameter-block" key={index}><h4>数据点 {index + 1}</h4><MetadataFields prefix={`数据点 ${index + 1}：`} fields={section.fields ?? []} value={point} onChange={next => edit(items.map((old, i) => i === index ? next : old))} /><Button danger onClick={() => edit(items.filter((_, i) => i !== index))}>删除数据点</Button></div>)}<Button onClick={() => edit([...items, {}])}>增加数据点</Button></> }; }
    if (section.keyed) { const items = item && typeof item === 'object' ? item as Parameters : {}; return { key: path, label: '动作映射', children: <>{Object.entries(items).map(([key, point]) => <div className="parameter-block" key={key}><h4>{key}</h4><MetadataFields prefix={key + '：'} fields={section.fields ?? []} value={point as Parameters} onChange={next => edit({ ...items, [key]: next })} /></div>)}<p>动作名称和扩展对象可在完整参数中编辑。</p></> }; }
    return { key: path, label: ({ connection: '连接', polling: '采样', address: '设备地址', report_strategy: '上报策略', 'connection.tls': 'TLS' } as Record<string, string>)[path] || path, children: <MetadataFields fields={section.fields ?? []} value={item && typeof item === 'object' ? item as Parameters : {}} onChange={edit} /> };
  })} />;
}

import { useEffect, useState } from 'react';
import { useMutation } from '@tanstack/react-query';
import { Alert, Button, Card, Descriptions, Drawer, Input, Select, Space, Table, Tabs, Tag } from 'antd';
import { json, useResource } from './api';
import { callOperation, type Contract } from './generated-client';
import { parseExactJSON } from './precision';
import { PageTitle, ErrorNotice, StateTag } from './views';
import { MetadataValidationScope, ProtocolParameterForm, type Parameters } from './metadata-form';
import type { Entity } from './types';

export function ProtocolConfigurations({ mode, initialID = '' }: { mode: string; initialID?: string }) {
  const protocols = useResource<Contract<'ProtocolMetadata'>[]>('/device-protocols'); const devices = useResource<Entity[]>('/entities');
  const connectors = useResource<Contract<'ConnectorConfigurationDetail'>[]>('/connector-configurations', 5000);
  const [deviceID, setDeviceID] = useState(initialID); const detail = useResource<Contract<'DeviceConfigurationDetail'>>(deviceID ? '/devices/' + encodeURIComponent(deviceID) + '/configuration' : null);
  const [editing, setEditing] = useState<{ kind: 'device' | 'connector'; protocol: string; id: string; version: unknown; allowed: boolean; group: string; edge: string }>();
  const [fieldErrors,setFieldErrors]=useState<string[]>([]); const [parameters, setParameters] = useState<Parameters>({}); const [raw, setRaw] = useState('{}'); const [rawError, setRawError] = useState(''); const [validation, setValidation] = useState<Contract<'Result'>>();
  const set = (value: Parameters) => { setParameters(value); setRaw(json(value)); setRawError(''); setValidation(undefined); };
  const openDevice = () => { if (!detail.data?.entity) return; const entity = detail.data.entity; set(detail.data.configuration?.parameters as Parameters ?? {}); setEditing({ kind: 'device', protocol: detail.data.configuration?.protocol ?? entity.protocol ?? '', id: entity.id ?? '', version: entity.version, allowed: !!detail.data.allowed_actions?.find(action => action.action === 'save' && action.allowed), group: entity.parent_id ?? 'factory', edge: entity.edge_id ?? '' }); };
  const openConnector = async (item: Contract<'ConnectorConfigurationDetail'>) => {
    const connector = item.configuration!;
    const result = await callOperation('post_device_configurations_validate', { body: { protocol: connector.protocol ?? '', config: connector.config } }, { exact: true });
    set(result.parameters as Parameters ?? {}); setEditing({ kind: 'connector', protocol: connector.protocol ?? '', id: connector.id ?? '', version: connector.version, allowed: !!item.allowed_actions?.find(action => action.action === 'save' && action.allowed), group: connector.group_id ?? 'factory', edge: connector.edge_id ?? '' });
  };
  useEffect(() => { if (initialID) setDeviceID(initialID); }, [initialID]);
  const validate = useMutation({ mutationFn: async () => { if (!editing) return; if (rawError || fieldErrors.length) throw new Error(rawError || fieldErrors.join('；')); const result = await callOperation('post_device_configurations_validate', { body: { protocol: editing.protocol, parameters: parameters as Contract<'Parameters'> } }, { exact: true }); setValidation(result); return result; } });
  const save = useMutation({ mutationFn: async () => {
    const result = await validate.mutateAsync(); if (!result?.valid || !editing) throw new Error('完成配置预检后保存参数');
    if (!editing.allowed) throw new Error('当前服务和身份未允许保存此配置');
    if (editing.kind === 'device') await callOperation('post_device_configurations', { body: { id: editing.id, request_id: crypto.randomUUID(), expected_version: editing.version as never, parameters: parameters as Contract<'Parameters'> } }, { exact: true });
    else await callOperation('post_connector_configurations', { body: { request_id: crypto.randomUUID(), expected_version: editing.version as never, group_id: editing.group, edge_id: editing.edge, protocol: editing.protocol, parameters: parameters as Contract<'Parameters'> } }, { exact: true });
    setEditing(undefined); await detail.reload(); await connectors.reload();
  }, onError: () => { void detail.reload(); void connectors.reload(); } });
  const metadata = protocols.data?.find(protocol => protocol.protocol === editing?.protocol || protocol.aliases?.includes(editing?.protocol ?? ''));
  return <><PageTitle title="协议与设备参数" note="依据协议目录编辑连接、采样、数据点和动作映射，并核对正式配置版本与下发回执。" /><ErrorNotice error={protocols.error || devices.error || connectors.error || detail.error} retry={() => { void protocols.reload(); void connectors.reload(); void detail.reload(); }} />
    <Card title="设备基础参数"><Space wrap><Select aria-label="参数设备" showSearch optionFilterProp="label" value={deviceID || undefined} placeholder="选择设备" onChange={setDeviceID} style={{ minWidth: 280 }} options={(devices.data ?? []).filter(device => device.kind === 'device').map(device => ({ value: device.id, label: device.name }))} /><Button disabled={!detail.data} onClick={openDevice}>编辑设备参数</Button></Space>{detail.data && <Descriptions className="section-card" column={2} items={[{ key: 'device', label: '设备', children: detail.data.entity?.name }, { key: 'version', label: '已阅版本', children: String(detail.data.entity?.version) }, { key: 'protocol', label: '协议', children: detail.data.configuration?.protocol }, { key: 'permission', label: '操作条件', children: detail.data.allowed_actions?.map(action => action.reason || action.action).join('；') }]} />}</Card>
    <Card title="正式连接器配置与下发状态" className="section-card"><Table rowKey={item => item.configuration?.id ?? ''} dataSource={connectors.data ?? []} scroll={{ x: 900 }} columns={[{ title: '配置身份', render: (_, item) => item.configuration?.id }, { title: '协议', render: (_, item) => item.configuration?.protocol }, { title: '配置版本', render: (_, item) => String(item.configuration?.version) }, { title: '归属节点', render: (_, item) => item.configuration?.edge_id }, { title: '已确认版本', render: (_, item) => String(item.receipt?.configuration_version ?? 0) }, { title: '下发状态', render: (_, item) => <><StateTag status={item.receipt?.status ?? 'pending'} />{item.receipt?.reason}</> }, { title: '操作', render: (_, item) => <Button onClick={() => void openConnector(item).catch(error => { setRawError(String(error)); })}>查看连接器参数</Button> }]} /></Card>
    <Drawer title={editing?.kind === 'device' ? '设备基础参数编辑' : '连接器参数编辑'} open={!!editing} onClose={() => setEditing(undefined)} width="min(920px, 100vw)" extra={<Space><Button loading={validate.isPending} onClick={() => validate.mutate()}>配置预检</Button><Button type="primary" disabled={!editing?.allowed} loading={save.isPending} onClick={() => save.mutate()}>保存参数</Button></Space>}>
      <Space wrap><Tag>{metadata?.label || editing?.protocol}</Tag><span>已阅版本 {String(editing?.version)}</span><span>服务模式 {mode}</span></Space>
      {!editing?.allowed && <Alert type="info" title="当前配置允许读取" description="保存操作由归属节点及当前授权决定，请使用归属节点的现场工作台。" />}
      {(rawError || validate.error || save.error) && <Alert type="error" title="参数操作未完成" description={rawError || validate.error?.message || save.error?.message} />}
      {save.error && <Button onClick={async () => {
        if (!editing) return;
        if (editing.kind === 'device') { const current = await detail.reload(); const value = current.data; if (value?.entity) setEditing({ ...editing, version:value.entity.version, allowed:!!value.allowed_actions?.some(action=>action.action==='save'&&action.allowed) }); }
        else { const current = await connectors.reload(); const value = current.data?.find(item=>item.configuration?.id===editing.id); if(value?.configuration) setEditing({...editing,version:value.configuration.version,allowed:!!value.allowed_actions?.some(action=>action.action==='save'&&action.allowed)}); }
        save.reset();
      }}>采用更新后的保存依据，保留已填写参数</Button>}
      {validation && <Alert type={validation.valid ? 'success' : 'error'} title={validation.valid ? '配置预检通过' : '配置预检存在问题'} description={validation.issues?.map(issue => `${issue.path}：${issue.message}`).join('；')} />}
      <MetadataValidationScope key={editing?.id} onChange={setFieldErrors}><Tabs items={[{ key: 'metadata', label: '元数据表单', children: metadata && <ProtocolParameterForm metadata={metadata} value={parameters} onChange={set} /> }, { key: 'raw', label: '完整参数与扩展', children: <><p>未修改的扩展字段与数据点扩展随同本次配置保存，数值使用精确 JSON 输入。</p><Input.TextArea aria-label="完整协议参数" rows={25} value={raw} onChange={event => { setRaw(event.target.value); try { const value = parseExactJSON(event.target.value); if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('参数需要 JSON 对象'); setParameters(value as Parameters); setRawError(''); setValidation(undefined); } catch (error) { setRawError(String(error)); } }} /></> }]} />
      </MetadataValidationScope>
    </Drawer></>;
}
